// Petición a OpenAI con el documento (PDF como archivo, foto como imagen) · doc-v1.0
const b = $json.body || {};
const tipo = String(b.tipo || '');
const datos = String(b.datos || '');
if (!datos || datos.length > 4500000 || !/^[A-Za-z0-9+/=]+$/.test(datos) || !['application/pdf', 'image/jpeg', 'image/png', 'image/webp'].includes(tipo)) {
  return [{ json: { invalido: true } }];
}
const contenido = tipo === 'application/pdf'
  ? { type: 'file', file: { filename: String(b.nombre || 'documento.pdf').slice(0, 100), file_data: 'data:application/pdf;base64,' + datos } }
  : { type: 'image_url', image_url: { url: 'data:' + tipo + ';base64,' + datos, detail: 'high' } };
return [{ json: { body: {
  model: 'gpt-4o-mini', temperature: 0,
  response_format: { type: 'json_schema', json_schema: { name: 'documento_r4', strict: true, schema: {"type":"object","additionalProperties":false,"required":["proveedor","fecha","numero","codigo_obra","tipo_documento","categoria","tipo_coste","base_imponible","iva","total","lineas"],"properties":{"proveedor":{"type":"string"},"fecha":{"type":"string"},"numero":{"type":"string"},"codigo_obra":{"type":"string"},"tipo_documento":{"type":"string","enum":["factura","albaran","ticket","nomina","recibo","otro"]},"categoria":{"type":"string","enum":["material","gasolina","alquiler","subcontrata","nomina_estructura","seguro","prevencion","oficina","vehiculo","herramientas","otros"]},"tipo_coste":{"type":"string","enum":["directo","indirecto"]},"base_imponible":{"type":"number"},"iva":{"type":"number"},"total":{"type":"number"},"lineas":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["concepto","importe"],"properties":{"concepto":{"type":"string"},"importe":{"type":"number"}}}}}} } },
  messages: [
    { role: 'system', content: "Eres el lector de documentos de R4 Rehabilitación de Estructuras (Mallorca, España).\nRecibes facturas, albaranes y tickets de proveedores (materiales, gasolina, alquileres, subcontratas) y a veces nóminas o recibos de seguros.\nExtrae SOLO lo que aparece en el documento; si un dato no aparece, usa cadena vacía o 0. No inventes.\n- proveedor: razón social de quien EMITE el documento (nunca R4).\n- fecha: fecha de emisión en formato AAAA-MM-DD.\n- numero: número de factura, albarán o ticket.\n- codigo_obra: código de obra de R4 si aparece (p. ej. «Obra 36», «Ref. obra: 36», «O-36», «Pedido obra 36» → «36»). Solo el código.\n- base_imponible: importe sin IVA. iva: cuota de IVA. total: importe total con IVA.\n- lineas: conceptos principales (máx. 12) con su importe sin IVA.\n- categoria: material, gasolina, alquiler, subcontrata, nomina_estructura, seguro, prevencion, oficina, vehiculo, herramientas u otros.\n- tipo_coste: «directo» si es material, gasolina, alquiler o subcontrata para una obra; «indirecto» si es estructura (oficina, seguros, prevención, nóminas de oficina, ordenadores)." },
    { role: 'user', content: [{ type: 'text', text: 'Extrae los datos de este documento.' }, contenido] }
  ]
} } }];

const r = $json;
if (r.invalido) return [{ json: { ok: false, error: 'archivo no válido (PDF, JPG, PNG o WEBP de hasta 3 MB)' } }];
try {
  const doc = JSON.parse(r.choices[0].message.content);
  return [{ json: { ok: true, version: 'doc-v1.0', documento: doc } }];
} catch (e) {
  return [{ json: { ok: false, error: 'la IA no pudo leer el documento', detalle: String((r.error && r.error.message) || e.message || '').slice(0, 200) } }];
}
